package fr.roadguard.app;
import android.app.AlertDialog;
import android.content.Intent;
import android.widget.*;
final class DriveAutoUi {
  static void show(MainActivity a){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);int padding=(int)(16*a.getResources().getDisplayMetrics().density);box.setPadding(padding,padding,padding,padding);TextView info=new TextView(a);info.setText("Au-dessus de 20 km/h sur deux mesures GPS fiables, les alertes démarrent. Après 1 minute à l’arrêt (moins de 3 km/h), les alertes et la bulle se coupent. Une veille GPS avec notification reste active pour détecter le prochain départ.\n\nPasser sur Waze garde le suivi. Fermer ROADGUARD depuis les applications récentes ou avec Retour arrête le suivi et retire la bulle. Après un arrêt forcé Android, rouvrez ROADGUARD pour réarmer le mode.\n\nUn GPS indisponible ne compte pas comme un arrêt : les alertes et la bulle sont suspendues jusqu’à une nouvelle détection de conduite.");box.addView(info);TextView state=new TextView(a);box.addView(state);Button bubble=new Button(a);bubble.setText("Armer avec la bulle");bubble.setOnClickListener(v->a.startFloatingRadar());box.addView(bubble);Button quiet=new Button(a);quiet.setText("Armer sans bulle");quiet.setOnClickListener(v->a.startBackgroundAlerts());box.addView(quiet);Button stop=new Button(a);stop.setText("Arrêter le mode auto");stop.setOnClickListener(v->{a.getPreferences(0).edit().putBoolean("monitor_armed",false).putBoolean("floating_auto",false).apply();BackgroundAlertService.stopMonitor(a);a.updateFloatingChip();});box.addView(stop);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Surveillance automatique").setView(box).setPositiveButton("Fermer",null).create();android.os.Handler h=new android.os.Handler(android.os.Looper.getMainLooper());Runnable refresh=new Runnable(){public void run(){if(!dialog.isShowing())return;state.setText(BackgroundAlertService.running?(BackgroundAlertService.monitoring?"Surveillance active":"Veille GPS · prochain départ au-dessus de 20 km/h"):"Mode auto arrêté");h.postDelayed(this,1000);}};dialog.setOnDismissListener(d->h.removeCallbacksAndMessages(null));dialog.show();h.post(refresh);}
  private DriveAutoUi(){}
}
